	public record LeafCostCall(PackedQueryView query, int relationId) {

		public PackedCostContext emptyContext() {
			return new PackedCostContext();
		}
	}

	public record StatementOnlyChainCostCall(PackedQueryView query, int[] relationIds) {

		public StatementOnlyChainCostCall {
			relationIds = relationIds.clone();
		}

		@Override
		public int[] relationIds() {
			return relationIds.clone();
		}

		public int relationId(int ordinal) {
			return relationIds[ordinal];
		}

		public PackedCostContext prefixContext(int prefixCount, double prefixRows) {
			if (prefixCount < 1 || prefixCount >= relationIds.length) {
				throw new IllegalArgumentException("Prefix must leave at least one factor to cost");
			}
			PackedCostContext context = new PackedCostContext();
			context.reset(relationIds, 0, prefixCount, prefixRows, 0);
			return context;
		}
	}

	public record StatementFactorChainCostCall(PackedQueryView query, int bindingRelationId,
			int[] factorRelationIds) {

		public StatementFactorChainCostCall {
			factorRelationIds = factorRelationIds.clone();
		}

		@Override
		public int[] factorRelationIds() {
			return factorRelationIds.clone();
		}

		public int factorRelationId(int ordinal) {
			return factorRelationIds[ordinal];
		}

		public PackedCostContext emptyContext() {
			return new PackedCostContext();
		}

		public PackedCostContext prefixContext(int prefixFactorCount, double prefixRows, int evidenceStateId) {
			if (prefixFactorCount < 0 || prefixFactorCount > factorRelationIds.length) {
				throw new IndexOutOfBoundsException("invalid packed statement-factor prefix length");
			}
			int[] prefixRelationIds = new int[prefixFactorCount + 1];
			prefixRelationIds[0] = bindingRelationId;
			System.arraycopy(factorRelationIds, 0, prefixRelationIds, 1, prefixFactorCount);
			PackedCostContext context = new PackedCostContext();
			context.reset(prefixRelationIds, 0, prefixRelationIds.length, prefixRows, evidenceStateId);
			return context;
		}

		public PackedCostContext factorOnlyContext(int factorOrdinal, double prefixRows, int evidenceStateId) {
			PackedCostContext context = new PackedCostContext();
			context.reset(new int[] { factorRelationId(factorOrdinal) }, 0, 1, prefixRows, evidenceStateId);
			return context;
		}

	}

	public record TwoFiniteComponentCostCall(PackedQueryView query, int outerBindingRelationId,
			int outerFactorRelationId, int componentBindingRelationId, int componentFactorRelationId) {

		public PackedCostContext emptyContext() {
			return new PackedCostContext();
		}

		public PackedCostContext outerFactorContext(double prefixRows, int evidenceStateId) {
			return prefixContext(new int[] { outerBindingRelationId }, prefixRows, evidenceStateId);
		}

		public PackedCostContext componentBindingContext(double prefixRows, int evidenceStateId) {
			return prefixContext(new int[] { outerBindingRelationId, outerFactorRelationId }, prefixRows,
					evidenceStateId);
		}

		public PackedCostContext componentFactorContext(double prefixRows, int evidenceStateId) {
			return prefixContext(
					new int[] { outerBindingRelationId, outerFactorRelationId, componentBindingRelationId },
					prefixRows, evidenceStateId);
		}

		private static PackedCostContext prefixContext(int[] relationIds, double prefixRows, int evidenceStateId) {
			PackedCostContext context = new PackedCostContext();
			context.reset(relationIds, 0, relationIds.length, prefixRows, evidenceStateId);
			return context;
		}
	}

